CREATE COLUMN TABLE "TEST_AP"."OSLP" ("SlpCode" INTEGER CS_INT NOT NULL , "SlpName" NVARCHAR(155) NOT NULL , "Memo" NVARCHAR(50), "Commission" DECIMAL(21,6) CS_FIXED, "GroupCode" SMALLINT CS_INT DEFAULT 0, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "EmpID" INTEGER CS_INT, "Active" NVARCHAR(1) DEFAULT 'Y', "Telephone" NVARCHAR(20), "Mobil" NVARCHAR(50), "Fax" NVARCHAR(20), "Email" NVARCHAR(100), "DPPStatus" NVARCHAR(1) DEFAULT 'N', "EncryptIV" NVARCHAR(100), PRIMARY KEY ("SlpCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OSLP_SLP_NAME" ON "TEST_AP"."OSLP" ( "SlpName" ASC );
CREATE INDEX "OSLP_COM_GROUP" ON "TEST_AP"."OSLP" ( "GroupCode" ASC )